async (url, options = {}) => {
    (__assertion("fixture:assert-1"), assert.equal(new URL(url).origin, config.ollamaEndpoint));
    (__assertion("fixture:assert-2"), assert.equal(options.redirect, 'error'));
    (__assertion("fixture:assert-3"), assert.ok(!Object.keys(options.headers ?? {}).some(key => ['authorization', 'x-api-key'].includes(key.toLowerCase()))));
    const path = new URL(url).pathname;
    const body = options.body ? JSON.parse(options.body) : undefined;
    calls.push({ path, body, signal: options.signal });
    if (path === '/api/version') return Response.json({ version });
    if (path === '/api/tags') return Response.json({ models: installed ? [{ name: config.ollamaModel }] : [] });
    if (path === '/api/show') return Response.json({ details: { parameter_size: '4B' }, ...(remote ? { remote_host: 'https://PRIVATE_HOST' } : {}) });
    if (path === '/api/ps') return residentResponse?.(calls) ?? Response.json({ models: [
      ...(resident ? [{ name: config.ollamaModel }] : []), ...others.map(name => ({ name })),
    ] });
    (__assertion("fixture:assert-4"), assert.equal(path, '/v1/systemone', 'No cloud, chat, downloads, unloads, or service control'));
    (__assertion("fixture:assert-5"), assert.equal(body.model, config.ollamaModel));
    (__assertion("fixture:assert-6"), assert.equal(body.keep_alive, config.ollamaKeepAlive));
    (__assertion("fixture:assert-7"), assert.notEqual(body.keep_alive, '0'));
    (__assertion("fixture:assert-8"), assert.ok(!JSON.stringify(body).includes('PRIVATE_KEY')));
    (__assertion("fixture:assert-9"), assert.ok(!JSON.stringify(body.state).includes('SYNTHETIC_REMINDER_ONLY')));
    (__assertion("fixture:assert-10"), assert.ok(!JSON.stringify(body.state).includes('Synthetic coding assistant guidance')));
    const index = decisions++;
    resident = true;
    const custom = await respond?.({ index, options, body });
    if (custom) return custom;
    const selected = index === 0 ? 'haiku' : choice ?? LOCAL_DIAGNOSTIC_CASES.find(item => item.prompt === body.state.current_task)?.expected;
    (__assertion("fixture:assert-11"), assert.ok(tiers.includes(selected), 'Each synthetic task survived the actual state extraction'));
    return Response.json({ model: config.ollamaModel, answers: { tier: { type: 'choice', choice: selected, confidence: 1,
      probabilities: Object.fromEntries(tiers.map(tier => [tier, tier === selected ? 1 : 0])) } }, usage: { input_tokens: 900, output_tokens: 1 } });
  }

